def page(slug, title, description, body, active=''):
    directory=OUT if slug=='404.html' else OUT / slug.strip('/')
    directory.mkdir(parents=True,exist_ok=True)
    title=title.replace('<br>',' ')
    visuals = {
        'compare': ('consultation', 'Notebook and pen ready for comparing questions', 'Understand the differences before a clinical conversation.'),
        'hymenoplasty': ('recovery', 'Folded rose linen and a glass of water in a restful home setting', 'Make room for recovery, questions, and your own pace.'),
        'labiaplasty': ('recovery', 'Rose linen and soft towels arranged in a quiet home setting', 'Consider comfort, recovery, and what matters to you.'),
        'perineoplasty': ('recovery', 'Folded linen beside a glass of water in soft window light', 'A considered approach to pelvic health and recovery.'),
        'find-care': ('canada', 'Illustrative mountain lake landscape in soft rose dawn light', 'Explore Canadian care with a little more perspective.'),
        'consultation-guide': ('consultation', 'Open blank notebook, pen and glasses on a blush desk', 'A little preparation can make a conversation clearer.'),
        'sources': ('consultation', 'Blank notebook and reading glasses in natural light', 'Space to read, reflect, and ask better questions.'),
        'privacy': ('consultation', 'Notebook and pen on a quiet rose-coloured desk', 'Understand the details before you decide what to share.'),
        'enquiry': ('consultation', 'A blank notebook ready for questions on a blush desk', 'Start with a question. Take the next step at your pace.'),
    }
    if slug in ('toronto','montreal','other-services','hymenectomy','bartholin-cyst-treatment','vaginismus-care','lichen-sclerosus-care','pessary-fitting'):
        visuals[slug] = ('consultation', 'Open notebook and pen on a soft rose desk', 'Specific concerns. Space for a thoughtful conversation.')
    if slug in visuals:
        asset,alt,caption = visuals[slug]
        visual = f'<figure class="editorial-banner wrap"><img src="/assets/{asset}.jpg" alt="{alt}" width="1536" height="1024" loading="lazy"><figcaption>{caption}</figcaption></figure>'
        body = body.replace('</section>', '</section>'+visual, 1)
    elif slug == 'about':
        body = body.replace('/assets/rose-anatomy-hero.jpg','/assets/consultation.jpg').replace('Abstract rose-coloured layered illustration inspired by vulval anatomy','Notebook and reading glasses in soft light, ready for a thoughtful conversation')
    elif slug == '':
        body = body.replace('<ol class="steps">','<ol class="steps">',1)
        body = body.replace('</div><ol class="steps">','<img class="editorial-inline" src="/assets/consultation.jpg" alt="Notebook and pen for preparing consultation questions" width="1536" height="1024" loading="lazy"></div><ol class="steps">',1)
        body = body.replace('<div class="region-list">','<div class="region-list"><img class="editorial-region" src="/assets/canada.jpg" alt="Illustrative Canadian mountain lake in rose dawn light" width="1536" height="1024" loading="lazy">',1)
        body = body.replace('<div class="procedure-secondary">','<div class="procedure-secondary">',1)

    body=body.replace('before<br><em>','before <br><em>').replace('make<br><em>','make <br><em>').replace('>← Back<','><span aria-hidden="true">←</span> Back<').replace('>← Edit choices<','><span aria-hidden="true">←</span> Edit choices<')
    content=f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><meta name="description" content="{html.escape(description,quote=True)}"><meta name="theme-color" content="#91425f"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src https://formspree.io; form-action https://formspree.io; base-uri 'none'; object-src 'none'"><title>{html.escape(title)} | hymen.ca</title><link rel="icon" href="/assets/favicon-pink-v2.ico" sizes="16x16 32x32 48x48" type="image/x-icon"><link rel="icon" href="/assets/favicon-pink-v2-96.png" sizes="96x96" type="image/png"><link rel="icon" href="/assets/favicon-pink-v2.svg" sizes="any" type="image/svg+xml"><link rel="apple-touch-icon" href="/assets/apple-touch-icon-pink-v2.png" sizes="180x180"><link rel="stylesheet" href="/assets/style.css"><script type="module" src="/assets/app.js"></script></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>'''
    (directory/('404.html' if slug=='404.html' else 'index.html')).write_text(content)

def intro(kicker, title, description):
    return f'<section class="page-intro wrap"><a class="breadcrumb" href="/">Home <span aria-hidden="true">/</span></a><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro-copy">{description}</p></section>'

def cta(title='Ready to discuss your options?'):
    return f'<section class="cta wrap"><div><p class="eyebrow">AT YOUR OWN PACE</p><h2>{title}</h2><p>Personal questions deserve care and respect. Start a consultation request without sharing intimate history or photographs. The decision to proceed is always yours.</p></div>{link("/enquiry/","Request a consultation","button light")}</section>'

def faq(q,a): return f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div class="answer">{a}</div></details>'

service_topics = [
 ('hymenectomy','Hymenectomy','HYMENAL CONDITIONS','Assessment and treatment of hymenal tissue that obstructs the opening.','hymenectomy',
  'A hymenectomy opens or removes hymenal tissue when a congenital variation causes obstruction or symptoms. A septate, microperforate or imperforate hymen may affect menstrual flow or tampon use. An examination establishes whether hymenal tissue is the cause.',
  'A clinician may recommend a procedure to remove the obstructing tissue. Discuss anaesthesia, bleeding, scarring and injury risks. Recovery instructions should cover activity, vaginal insertion and follow-up; use your clinician’s clearance rather than a general timeline.',
  'After a procedure, seek medical care for heavy bleeding, fever, pus-like discharge or dizziness.',
  ['Which finding explains my symptoms?', 'What tissue would be treated, and why?', 'Who will assess healing before I resume activities?']),
 ('bartholin-cyst-treatment','Bartholin’s cyst treatment','GLAND & CYST CARE','Understand assessment, drainage and care for a recurring cyst.','bartholin',
  'A Bartholin’s cyst can appear as a lump on one side near the vaginal opening. Some are painless; an infection can cause an abscess. Have a new lump checked rather than assuming its cause.',
  'Some cysts need no treatment. Depending on infection and recurrence, care may include antibiotics or drainage. A clinician may place a small catheter or create an opening for continued drainage. Do not squeeze or drain a cyst yourself.',
  'Seek urgent care if a lump rapidly becomes larger or more painful, contains pus, or comes with fever or feeling unwell.',
  ['What confirms the diagnosis?', 'Why do you recommend this drainage approach?', 'What is the plan if it returns?']),
 ('vaginismus-care','Vaginismus care','PELVIC COMFORT','Explore supported care for involuntary tightening and penetration pain.','vaginismus',
  'Vaginismus involves involuntary tightening when vaginal insertion is attempted. It may affect tampon use, examinations or penetration. The reaction is not something a person chooses. Other conditions can also cause pain, so assessment matters.',
  'Care may combine psychosexual therapy, relaxation, pelvic floor exercises and gradual vaginal trainers under specialist guidance. Discuss what an examination involves and what would make it more comfortable. A treatment plan should reflect your goals.',
  'Speak with a primary care clinician or sexual health service if you think you have vaginismus. Ask about assessment for other causes of pain and an appropriate specialist referral.',
  ['How can we make the assessment comfortable?', 'Who will guide therapy and review progress?', 'Can we agree on goals that matter to me?']),
 ('lichen-sclerosus-care','Vulval lichen sclerosus care','VULVAL SKIN HEALTH','A guide to diagnosis, prescribed treatment and ongoing review.','lichen',
  'Lichen sclerosus can cause itchy white patches and fragile genital skin. It is not contagious or caused by poor hygiene. Scarring may cause tightness and discomfort. Skin changes need examination to establish their cause.',
  'Prescription steroid ointment is commonly used to control symptoms. There is no cure, so follow-up and an individual maintenance plan matter. A clinician can explain medication use and whether specialist assessment is needed.',
  'Arrange review for a new lump, thickened area or an ulcer that does not heal. Lichen sclerosus carries a small increased risk of vulval cancer; ask how to monitor changes.',
  ['How certain is the diagnosis?', 'How should I use and review my prescription?', 'Which skin changes should prompt an appointment?']),
 ('pessary-fitting','Pessary fitting for prolapse','PELVIC SUPPORT','Explore a support device alongside other prolapse care options.','prolapse',
  'Pelvic organ prolapse occurs when pelvic organs bulge into the vagina. Symptoms can include a bulge, pressure or bladder and bowel difficulties. An assessment identifies the type and severity of prolapse.',
  'A vaginal support pessary is a plastic or silicone device that supports pelvic organs. Other options may include physiotherapy, hormone treatment or surgery. If symptoms are not troublesome, treatment may not be needed. The choice depends on your assessment and preferences.',
  'Have a vaginal lump or symptoms of prolapse checked. Discuss a fitting and follow-up plan with the clinician rather than choosing a device from symptoms alone.',
  ['Could a pessary meet my goals?', 'Who handles fitting, cleaning and follow-up?', 'What should I do if the device is uncomfortable?']),
]

