def article(slug,kicker,title,desc,sections,refs):
    toc=''.join(f'<a href="#{sid}">{heading}</a>' for sid,heading,_ in sections)
    content=''.join(f'<section id="{sid}" class="article-section"><h2>{heading}</h2>{copy}</section>' for sid,heading,copy in sections)
    if slug in ('hymenoplasty','labiaplasty'):
        content = '<figure class="guide-figure"><a href="/assets/hymen-anatomy.svg" target="_blank" rel="noopener"><img src="/assets/hymen-anatomy.svg" alt="Two common hymenal shapes: crescent-shaped and ring-shaped tissue" width="1000" height="880"></a><figcaption>Educational illustration of two common shapes. Anatomy varies; this is not a before-and-after result. <a href="https://my.clevelandclinic.org/health/body/22718-hymen" target="_blank" rel="noopener noreferrer">Anatomy reference: Cleveland Clinic ↗</a></figcaption></figure>' + content

    body=intro(kicker,title,desc)+f'<div class="article-layout wrap"><aside class="article-nav"><p class="eyebrow">IN THIS GUIDE</p>{toc}<a href="/compare/">Compare procedures ↗</a><div class="aside-note"><span class="eyebrow">TAKE YOUR TIME</span><p>A consultation is a conversation, not a commitment.</p>{link("/enquiry/","Request a consultation","text-link")}</div></aside><article class="article-body"><div class="article-meta">Patient information · Canada · Sources checked 8 September 2026</div>{content}<section class="article-section sources-inline"><h2>Read the sources</h2>{"".join(src(k) for k in refs)}<p class="fine">Educational summary; not individually tailored medical advice. This content has not been clinically reviewed by hymen.ca.</p></section></article></div>'+cta()
    page(slug,title,desc,body,'procedures')

article('hymenoplasty','THE HYMENOPLASTY GUIDE','Hymenoplasty in Canada.','Understand the procedure, the evidence, and the questions that deserve a clear answer.',[
 ('understanding','What is hymenoplasty?','<p>Hymenoplasty is surgery intended to reconstruct or alter hymenal tissue at the vaginal opening. You may see it described as “hymen repair” or “hymen restoration.”</p>'+src('tcc')+'<p>It is different from treatment for a hymenal condition that obstructs menstrual flow or causes other symptoms. Those concerns need a medical assessment.</p>'+src('hymenectomy')),
 ('expectations','Start with realistic expectations.','<div class="callout"><h3>A hymen is not a record of sexual history.</h3><p>No examination can prove whether someone has had vaginal intercourse. Surgery cannot restore “virginity.”</p></div>'+src('who')+'<p>Bleeding after later intercourse is not assured, even after hymenoplasty. Do not base a decision on a promise of bleeding, invisibility, or a particular partner’s response.</p>'+src('danino')),
 ('evidence','What does the evidence say?','<p>The Society of Obstetricians and Gynaecologists of Canada states that genital cosmetic procedures for non-medical reasons cannot be supported by current rigorous evidence of safety and effectiveness. That is an important limitation to discuss, even when a clinic offers a procedure.</p>'+src('sogc')),
 ('risks','Risks to discuss.','<p>Potential complications of genital cosmetic surgery include pain, bleeding, infection, scarring, changes in sensation, painful intercourse, and further surgery. Evidence about long-term benefits is limited.</p><p>Ask a clinician how these risks relate to your health and the specific technique being proposed. Results and complication-free healing cannot be guaranteed.</p>'+src('acog')),
 ('recovery','Recovery is individual.','<p>Recovery advice differs by procedure and clinician. Arrange a written plan for time away from work, activity restrictions, follow-up, and whom to contact if problems arise. Do not use a short advertised downtime as permission to resume intercourse.</p><p>Ask: “When will you reassess healing, and which activities should wait for your clearance?”</p>'),
 ('costs','Cost, travel, and your consultation.','<p>Request a personalised quote in Canadian dollars. Ask whether it includes anaesthesia, facility charges, follow-up, taxes where applicable, and treatment of complications. If travelling, clarify where aftercare will happen and who will manage it once you return home.</p><p>You can choose not to proceed. If someone is pressuring you into surgery, ask to speak with a healthcare professional alone.</p>'+link('/find-care/','Explore public provider pages','text-link')),
],['who','sogc','acog','tcc','danino'])

article('labiaplasty','THE LABIAPLASTY GUIDE','Labiaplasty, with perspective.','A guide to labial surgery, normal variation, and a considered conversation about your goals.',[
 ('understanding','Understand the anatomy.','<p>The vulva is the external genital area. The vagina is the internal canal. Labiaplasty changes the labia, most commonly by reducing or reshaping the inner folds, called the labia minora.</p><p>Visible, uneven, or differently sized labia can be normal. There is no single appearance that a healthy vulva needs to have.</p>'+src('nhs')),
 ('assessment','Begin with your concerns.','<p>If you have rubbing, pain, or irritation, speak with a clinician before assuming surgery is the answer. An assessment may identify another cause or options that do not involve an operation.</p><p>If your concern is appearance, discuss your expectations openly. Surgery does not guarantee improved confidence or satisfaction with your body.</p>'+src('nhs')),
 ('risks','Risks and limitations.','<p>Possible complications include bleeding, infection, scarring, and reduced genital sensitivity. Surgery also carries anaesthetic risks. Discuss both the expected result and the possibility of an unwanted outcome.</p>'+src('nhs')+'<p>The Canadian guideline highlights the lack of rigorous evidence for non-medically indicated genital cosmetic procedures.</p>'+src('sogc')),
 ('recovery','Plan for healing, not just downtime.','<p>The NHS notes that time off work may extend to two weeks and full skin healing may take months. Your surgeon should give individual restrictions for exercise, intercourse, and work.</p>'+src('nhs')+'<p>Before choosing a provider, ask what support is included if recovery takes longer than expected.</p>'),
 ('questions','Bring these questions.','<ul class="check-list"><li>Is my anatomy within normal variation?</li><li>Could my symptoms have another cause?</li><li>Which non-surgical options should I consider?</li><li>How could sensation or comfort change?</li><li>What happens if I am unhappy with the result?</li></ul>')
],['nhs','sogc','acog'])

article('perineoplasty','PERINEAL & PELVIC HEALTH','The right care starts<br>with the right assessment.','Understand perineoplasty and why pelvic symptoms deserve an individual clinical conversation.',[
 ('understanding','What is perineoplasty?','<p>Perineoplasty repairs or changes tissue in the perineum, the area between the vaginal opening and the anus. It may be considered for scarring or changes after childbirth, or for cosmetic concerns.</p><p>It is not the same as vaginoplasty, which involves the internal vaginal canal.</p>'+src('cleveland')),
 ('assessment','Symptoms come before a procedure.','<p>Speak with a primary care clinician or gynaecologist about pain, scar discomfort, urinary symptoms, or a feeling of pelvic pressure. Ask whether a pelvic health specialist or pelvic floor physiotherapist would be appropriate.</p><p>A consultation should distinguish a medical problem from a cosmetic preference. “Tightening” is not a diagnosis or a guaranteed improvement in sexual function.</p>'+src('cleveland')),
 ('risks','Recovery and risks.','<p>Potential risks include bleeding, infection, pain, scarring, altered sensation, painful intercourse, or further surgery. Cleveland Clinic describes recovery commonly taking six to eight weeks; your own instructions depend on your procedure and health.</p><p>Discuss alternatives, future pregnancy plans, activity restrictions, and aftercare before making a decision.</p>'+src('cleveland')),
 ('energy','What about “vaginal rejuvenation”?','<p>This marketing term can refer to very different procedures. Ask for the exact treatment and the condition it is meant to address. We do not list laser, radiofrequency, or injectable treatments as proven ways to rejuvenate the vagina.</p><p>For a device-based treatment, ask whether the specific device is licensed by Health Canada for the proposed use, what evidence supports it, and what harms have been reported. A device licence for one use does not establish benefit for every advertised use.</p>'+src('hc')),
 ('questions','Questions for specialist care.','<ul class="check-list"><li>What is causing my symptoms?</li><li>Would non-surgical treatment be appropriate first?</li><li>What tissue would the proposed surgery change?</li><li>How will you measure whether treatment has helped?</li><li>Who will support my recovery?</li></ul>')
],['cleveland','sogc','acog','hc'])

